<script>
// พิมพ์: โหลดภาพทั้งหมดก่อน (ภาพตั้งเป็น lazy) แล้วจึงเปิดหน้าต่างพิมพ์ — เลือก "บันทึกเป็น PDF" ได้
document.getElementById('manPrint').addEventListener('click', async e => {
  const btn = e.currentTarget, old = btn.innerHTML;
  btn.disabled = true; btn.innerHTML = '<span class="spinner-border spinner-border-sm"></span> กำลังเตรียมภาพ…';
  const imgs = [...document.querySelectorAll('.man-fig img')];
  imgs.forEach(i => { i.loading = 'eager'; });
  await Promise.all(imgs.map(i => i.complete && i.naturalWidth ? null : new Promise(ok => { i.addEventListener('load', ok, { once: true }); i.addEventListener('error', ok, { once: true }); })));
  btn.disabled = false; btn.innerHTML = old;
  window.print();
});
</script>
